/* ============ Helpers ============ */
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
function div(a,b){return (b&&isFinite(a))?a/b:null}
function pct(a,b){const r=div(a,b);return r==null?null:r*100}
function growth(a,b){if(b==null||!isFinite(b)||b===0||a==null)return null;return (a-b)/Math.abs(b)*100}
const nf=new Intl.NumberFormat("en-US",{maximumFractionDigits:0});
function fmtCur(v){if(v==null)return "—";const a=Math.abs(v);if(a>=1e9)return (v/1e9).toFixed(2)+" مليار";if(a>=1e6)return (v/1e6).toFixed(2)+" مليون";if(a>=1e3)return (v/1e3).toFixed(1)+" ألف";return nf.format(v)}
function cur(){return (CO()&&CO().currency)||"ر.س"}
function fmt(v,u){
  if(v==null||!isFinite(v))return "—";
  if(u==="%")return `<span class="num">${v.toFixed(1)}%</span>`;
  if(u==="x")return `<span class="num">${v.toFixed(2)}×</span>`;
  if(u==="days")return `<span class="num">${Math.round(v)}</span> يوم`;
  if(u==="mo")return `<span class="num">${v.toFixed(1)}</span> شهر`;
  if(u==="sc")return `<span class="num">${v.toFixed(2)}</span>`;
  if(u==="cur"){const s=fmtCur(v).split(" ");return `<span class="num">${s[0]}</span>${s[1]?" "+s[1]:""} ${esc(cur())}`}
  return `<span class="num">${v}</span>`;
}
function fmtPlain(v,u){if(v==null||!isFinite(v))return "—";if(u==="%")return v.toFixed(1)+"%";if(u==="x")return v.toFixed(2)+"x";if(u==="days")return Math.round(v)+" يوم";if(u==="mo")return v.toFixed(1)+" شهر";if(u==="sc")return v.toFixed(2);if(u==="cur")return fmtCur(v)+" "+cur();return String(v)}
function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("on");clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove("on"),2800)}
function normAr(s){return String(s??"").toLowerCase().replace(/[\u064B-\u0652\u0640]/g,"").replace(/[أإآ]/g,"ا").replace(/ة/g,"ه").replace(/ى/g,"ي").replace(/[^\p{L}\p{N}&\- ]/gu," ").replace(/\s+/g," ").trim()}
function parseNum(v){if(typeof v==="number")return v;if(v==null)return null;let s=String(v).trim();if(!s)return null;
  s=s.replace(/[٠-٩]/g,d=>"٠١٢٣٤٥٦٧٨٩".indexOf(d)).replace(/٫/g,".").replace(/[٬,\s]/g,"");
  let neg=false;if(/^\(.*\)$/.test(s)){neg=true;s=s.slice(1,-1)}if(s.endsWith("-")){neg=true;s=s.slice(0,-1)}
  const n=parseFloat(s);return isNaN(n)?null:(neg?-n:n)}
function pid(y,m){return m?`${y}-${String(m).padStart(2,"0")}`:`${y}-A`}
function plabel(p){if(p&&p._label)return p._label;return p.month?`${MONTHS[p.month]} ${p.year}`:`سنة ${p.year}`}
function pkey(p){return p.year*100+(p.month||0)}
function daysIn(p){if(!p)return 30;if(p.days)return p.days;return p.month?new Date(p.year,p.month,0).getDate():365}
function uid(prefix){return prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function localYmd(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function today(){return localYmd(new Date())}
function addDays(n){const d=new Date();d.setDate(d.getDate()+n);return localYmd(d)}
function fmtDate(s){if(!s)return "—";const d=new Date(s);return isNaN(d)?s:d.toLocaleDateString("ar-SA-u-ca-gregory-nu-latn",{year:"numeric",month:"short",day:"numeric"})}
function clone(o){return JSON.parse(JSON.stringify(o??null))}
const isEmail=s=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s||"").trim());

const ROLES={admin:"مدير النظام",analyst:"محلل مالي",viewer:"مشاهد"};
const STATUS={open:"مفتوحة",progress:"قيد التنفيذ",closed:"مغلقة"};
