/* ---- in-app confirm / prompt (native dialogs are blocked inside the hosted frame) ---- */
function dlg2(){let d=document.getElementById("dlg2");if(!d){d=document.createElement("dialog");d.id="dlg2";document.body.appendChild(d)}return d}
function appConfirm(msg,opt={}){return new Promise(res=>{const d=dlg2();
  d.innerHTML=`<div class="dlg-h"><h3>${esc(opt.title||"تأكيد")}</h3></div><div class="dlg-b"><p style="margin:0;white-space:pre-wrap">${esc(msg)}</p></div>
   <div class="dlg-f"><button class="btn ${opt.danger?"danger":"primary"}" id="acOk">${esc(opt.ok||"متابعة")}</button><button class="btn ghost" id="acNo">إلغاء</button></div>`;
  let done=false;const fin=v=>{if(done)return;done=true;d.close();res(v)};
  d.querySelector("#acOk").onclick=()=>fin(true);d.querySelector("#acNo").onclick=()=>fin(false);d.oncancel=e=>{e.preventDefault();fin(false)};
  d.showModal();setTimeout(()=>d.querySelector("#acOk").focus(),30)})}
function appPrompt(msg,opt={}){return new Promise(res=>{const d=dlg2();
  d.innerHTML=`<div class="dlg-h"><h3>${esc(opt.title||"إدخال")}</h3></div><div class="dlg-b"><label style="font-size:14px">${esc(msg)}</label><textarea id="apIn" style="min-height:90px">${esc(opt.value||"")}</textarea><div class="lg-err" id="apErr"></div></div>
   <div class="dlg-f"><button class="btn primary" id="apOk">${esc(opt.ok||"حفظ")}</button><button class="btn ghost" id="apNo">إلغاء</button></div>`;
  let done=false;const fin=v=>{if(done)return;done=true;d.close();res(v)};
  d.querySelector("#apOk").onclick=()=>{const v=d.querySelector("#apIn").value.trim();if(opt.required&&!v){d.querySelector("#apErr").textContent="هذا الحقل مطلوب";return}fin(v)};
  d.querySelector("#apNo").onclick=()=>fin(null);d.oncancel=e=>{e.preventDefault();fin(null)};
  d.showModal();setTimeout(()=>d.querySelector("#apIn").focus(),30)})}
function fmtDT(t){if(!t)return "—";const d=new Date(t);return isNaN(d)?"—":d.toLocaleString("ar-SA-u-ca-gregory-nu-latn",{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}
