    <optgroup label="سنة كاملة">${years.map(y=>`<option value="Y:${y}" ${val==="Y:"+y?"selected":""}>سنة ${y} كاملة</option>`).join("")}${ann.filter(a=>!years.includes(a.year)).map(a=>`<option value="Y:${a.year}" ${val==="Y:"+a.year?"selected":""}>سنة ${a.year} (سنوي)</option>`).join("")}</optgroup>
