function tbClassify(l){
  if(/^9{4,}$/.test(l.ac)||/undistributed profit/i.test(l.nm))return {lbl:"متجاهل: سطر إقفال آلي في Odoo",st:"ign"};
  const cl=(l.cd||0)-(l.cr||0);let f=tbMap(l.ac,null,cl);
  if(!f){const k=l.ac[0];f=k==="1"?"otherCA":k==="2"?"otherCL":k==="3"?"equity":k==="4"?"otherIncome":"opex";return {lbl:TB_CLASS[f]+" (تقديري: حساب غير معروف)",st:"guess"}}
  if(f.endsWith("?"))return {lbl:TB_CLASS[f.slice(0,-1)]+" (تقديري حسب رقم الحساب)",st:"guess"};
  if(f==="byCenter"){const prod=normAr(l.sec||"").includes("انتاج");return {lbl:prod?"تكلفة المبيعات (مركز إنتاجي)":"مصروفات تشغيلية (مركز "+(l.sec||"غير محدد")+")",st:"ok"}}
  return {lbl:TB_CLASS[f]||f,st:"ok"};
}
