/* ============ Two-period comparison ============ */
const CMP_LINES=[
 {sec:"قائمة الدخل",rows:[["revenue","الإيرادات / المبيعات","up"],["cogs","تكلفة المبيعات (دون الإهلاك)","down"],["gp","مجمل الربح","up",1],["opex","المصروفات التشغيلية","down"],["ebitda","الربح قبل الفوائد والزكاة والاستهلاك EBITDA","up",1],
   ["depreciation","الاستهلاك والإطفاء (الإجمالي)","down"],["ebit","الربح التشغيلي","up",1],["interest","تكاليف التمويل","down"],["otherIncome","إيرادات (مصروفات) أخرى","up"],["tax","الزكاة والضريبة","down"],["ni","صافي الربح","up",1],["totalExp","إجمالي المصروفات والتكاليف","down",1]]},
 {sec:"الميزانية",rows:[["cash","النقد وما في حكمه","up"],["receivables","الذمم المدينة (العملاء والشقيقة التجارية)","n"],["icRT","منها: أرصدة تجارية مدينة للشقيقة","n"],["inventory","المخزون (الإجمالي)","n"],["spares","منها: مخزون قطع الغيار","down"],["prodInv","مخزون الإنتاج (دون قطع الغيار)","n"],["otherCA","أصول متداولة أخرى","n"],["icRN","منها: أرصدة مدينة بالإنابة للشقيقة","down"],["ca","إجمالي الأصول المتداولة","n",1],["nonCurrent","الأصول غير المتداولة","n"],["ta","إجمالي الأصول","up",1],
   ["payables","الذمم الدائنة (الموردون والشقيقة التجارية)","n"],["icPT","منها: أرصدة تجارية دائنة للشقيقة","n"],["shortDebt","قروض قصيرة الأجل","down"],["otherCL","مطلوبات متداولة أخرى","n"],["icPN","منها: أرصدة دائنة بالإنابة للشقيقة","n"],["cl","إجمالي المطلوبات المتداولة","down",1],["longDebt","قروض طويلة الأجل","down"],["otherNCL","مطلوبات غير متداولة أخرى","n"],["partners","منها: جاري الشركاء","n"],["tl","إجمالي المطلوبات","down",1],["equity","حقوق الملكية","up",1],["capital","منها: رأس المال المدفوع","n"],["retained","منها: الأرباح المبقاة (الخسائر المتراكمة)","up"]]},
 {sec:"مراقبة قطع الغيار",rows:[["sparesPurch","مشتريات قطع الغيار","down"],["sparesIssued","المنصرف للصيانة","n"],["sparesDisposed","المصرّف (بيع/نقل/إتلاف)","up"],["sparesSlow","بطيئة الحركة","down"],["sparesDead","راكدة","down"],["sparesProv","مخصص التقادم","n"]]},
 {sec:"التدفقات النقدية",rows:[["ocf","التدفق النقدي التشغيلي","up"],["capex","النفقات الرأسمالية","n"],["fcf","التدفق النقدي الحر","up",1]]}
];
function lineVal(c,k){if((k==="capital"||k==="retained")&&!c.has(k))return null;if(k==="partners"&&!c.has(k))return null;if((k==="spares"||k==="prodInv")&&!c.has("spares"))return null;if(["tradeRec","icRN","tradePay","icPN","icRT","icPT"].includes(k)&&!c.hasIC)return null;if(ALLF.some(f=>f.k===k)&&!c.has(k)&&k.startsWith("spares"))return null;if(k==="fcf")return c.has("ocf")?c.ocf-c.capex:null;if(["ocf","capex"].includes(k)&&!c.has(k))return null;const v=c[k];return typeof v==="number"&&isFinite(v)?v:null}
function curH(v){if(v==null)return "—";const s=fmtCur(v).split(" ");return `<span class="num">${s[0]}</span>${s[1]?" "+s[1]:""}`}
function judge(a,b,dir){if(a==null||b==null||dir==="n")return "na";const d=b-a;if(Math.abs(d)<1e-9)return "na";return (dir==="up"?d>0:d<0)?"good":"bad"}
function pctChg(a,b){if(a==null||b==null||a===0)return null;return (b-a)/Math.abs(a)*100}
