  let st=UI.cmp[UI.cid]||{};
  if(!anyPeriod(UI.cid,st.a)||!anyPeriod(UI.cid,st.b)){
    const months=all.filter(p=>p.month);const last=(months.length?months:all)[(months.length?months:all).length-1];
    const yoy=last.month?D.periods[UI.cid+"__"+pid(last.year-1,last.month)]:null;
    const prev=(months.length>1?months:all).filter(p=>p._id!==last._id).pop();
    st={a:yoy?pid(last.year-1,last.month):pid(prev.year,prev.month),b:pid(last.year,last.month)};UI.cmp[UI.cid]=st;saveUI();
  }
