  const opt=sel=>{const m=all.filter(p=>p.month),a=all.filter(p=>!p.month);const o=l=>[...l].reverse().map(p=>{const id=pid(p.year,p.month);return `<option value="${id}" ${id===sel?"selected":""}>${plabel(p)}</option>`}).join("");
    return (m.length?`<optgroup label="شهرية">${o(m)}</optgroup>`:"")+(a.length?`<optgroup label="سنوية">${o(a)}</optgroup>`:"")};
  const la=plabel(pa),lb=plabel(pb);
