  const krows=KPIS.map(k=>{const cfg=kcfg(k,UI.cid);const A=kpiStatusAt(k,pa),B=kpiStatusAt(k,pb);const d=(A.v!=null&&B.v!=null)?B.v-A.v:null;return {k,cfg,A,B,d,j:judge(A.v,B.v,cfg.dir)}});
  const imp=krows.filter(r=>r.j==="good").length,det=krows.filter(r=>r.j==="bad").length;
  const gA=krows.filter(r=>r.A.st==="good").length,gB=krows.filter(r=>r.B.st==="good").length;
