  h+=`<tr class="sec"><td colspan="${ok.length+1+(multi||dcol?1:0)}">المطابقة مع النقد</td></tr>`;xrows.push(["المطابقة مع النقد"]);
  rec.forEach(([l,f],i)=>{const vals=ok.map(f);const sumable=i===0;
    h+=`<tr class="${i===0||i===4?"tot":""}"><td>${l}</td>${vals.map(v=>`<td>${i===4?(Math.abs(v)<1?`<span class="chg good">مطابقة ✓</span>`:`<span class="chg bad">${cfParen(v)}</span>`):cfParen(v)}</td>`).join("")}${multi?`<td>${sumable?cfParen(vals.reduce((a,b)=>a+b,0)):""}</td>`:""}${dcol?`<td>${i<4?cfParen(vals[1]-vals[0]):""}</td>`:""}</tr>`;
    xrows.push([l,...vals,...(multi?[sumable?vals.reduce((a,b)=>a+b,0):""]:[])])});
