    if(!cf.eosOK)notes.push(`${plabel(r.p)}: رصيد مخصص نهاية الخدمة غير مدخل للفترتين، فظهرت حركته ضمن المطلوبات غير المتداولة الأخرى.`);
    if(!cf.zOK)notes.push(`${plabel(r.p)}: رصيد الزكاة المستحقة غير مدخل للفترتين، فظهرت الزكاة ضمن حركة المطلوبات المتداولة الأخرى.`);
    if(Math.abs(cf.diff)>=1)notes.push(`${plabel(r.p)}: فرق المطابقة سببه عدم توازن ميزانية إحدى الفترتين.`);
