    const open=c0&&c0.has("spares")?c0.spares:null;const calc=open!=null?open+c.sparesPurch-c.sparesIssued-c.sparesDisposed+(Number(p.data?.sparesAdj)||0):null;
    const movement=["sparesPurch","sparesIssued","sparesDisposed"].some(k=>c.has(k));
