/* ============ Prices & cost analysis ============ */
const TERMS={ex:"أرض المصنع",del:"واصل للعميل"};
function aggItems(list,kind,terms){
  const m={};(list||[]).filter(x=>!terms||x.terms===terms).forEach(x=>{const key=kind==="sales"?`${x.item}|${x.terms}|${x.unit||""}`:`${x.item}|${x.unit||""}`;
    const o=m[key]=m[key]||{key,item:x.item,terms:x.terms,unit:x.unit||"",qty:0,value:0,pSum:0,pN:0,used:0,hasUsed:false};
    const q=Number(x.qty)||0;const pr=x.price!=null&&x.price!==""?Number(x.price):(q?(Number(x.value)||0)/q:null);
    o.qty+=q;o.value+=(x.value!=null&&x.value!=="")?(Number(x.value)||0):(pr!=null&&q)?pr*q:0;if(pr!=null){o.pSum+=pr;o.pN++}
    if(x.used!=null&&x.used!==""){o.used+=Number(x.used)||0;o.hasUsed=true}});
  Object.values(m).forEach(o=>{o.price=o.qty>0&&o.value>0?o.value/o.qty:(o.pN?o.pSum/o.pN:null)});return m;
}
function priceIndex(listB,listA,kind,terms){
  if(!listB||!listA)return {idx:null,effect:null,matched:0,weighted:false};
  const B=aggItems(listB,kind,terms),A=aggItems(listA,kind,terms);const pairs=[];
  Object.values(B).forEach(b=>{const a=A[b.key];if(a&&a.price>0&&b.price>0)pairs.push({a,b,q:kind==="mats"?(b.hasUsed?b.used:b.qty):b.qty})});
  if(!pairs.length)return {idx:null,effect:null,matched:0,weighted:false};
  if(pairs.every(x=>x.q>0)){let eff=0,base=0;pairs.forEach(x=>{eff+=(x.b.price-x.a.price)*x.q;base+=x.a.price*x.q});return {idx:base>0?eff/base*100:null,effect:eff,matched:pairs.length,weighted:true}}
  const idx=pairs.reduce((s,x)=>s+(x.b.price/x.a.price-1),0)/pairs.length*100;return {idx,effect:null,matched:pairs.length,weighted:false};
}
function salesEffect(sp,cb){if(sp.idx==null)return {v:0,est:false};if(sp.weighted)return {v:sp.effect,est:false};if(!(cb.revenue>0))return {v:0,est:false};return {v:cb.revenue-cb.revenue/(1+sp.idx/100),est:true}}
