function prCard(t,v,j,sub){return `<div class="stat" style="min-width:220px;flex:1"><span>${t}</span><div style="display:flex;align-items:center;gap:8px;margin-top:4px"><b style="font-size:20px">${v}</b>${j&&j!=="na"?`<i class="dot ${j}"></i>`:""}</div><span>${sub}</span></div>`}
function priceNarrative(sp,mp,ca,cb,la,lb){
  const out=[];const rB=cb.revenue>0?cb.cogs/cb.revenue*100:null;
  if(sp.idx!=null&&cb.revenue>0){const rNo=cb.cogs/(cb.revenue-sp.effect)*100;const d=rB-rNo;
    out.push(`أسعار البيع ${sp.idx>=0?"ارتفعت":"انخفضت"} ${Math.abs(sp.idx).toFixed(1)}% على نفس الأصناف، ف${sp.effect>=0?"زادت":"نقصت"} الإيرادات ${nf.format(Math.abs(Math.round(sp.effect)))} ريال، و${d>=0?"رفعت":"خفّضت"} نسبة تكلفة المبيعات ${Math.abs(d).toFixed(1)} نقطة.`)}
  if(mp.idx!=null&&cb.revenue>0){const rNo=(cb.cogs-mp.effect)/cb.revenue*100;const d=rB-rNo;
    out.push(`أسعار شراء المواد الخام ${mp.idx>=0?"ارتفعت":"انخفضت"} ${Math.abs(mp.idx).toFixed(1)}%، ف${mp.effect>=0?"زادت":"نقصت"} تكلفة المبيعات ${nf.format(Math.abs(Math.round(mp.effect)))} ريال، و${d>=0?"رفعت":"خفّضت"} نسبة تكلفة المبيعات ${Math.abs(d).toFixed(1)} نقطة.`)}
  if(sp.idx!=null&&mp.idx!=null){const net=sp.effect-mp.effect;out.push(net>=0?`صافي أثر الأسعار إيجابي بمقدار ${nf.format(Math.round(net))} ريال على مجمل الربح: الشركة تمرّر تغير التكلفة إلى أسعار البيع.`:`صافي أثر الأسعار سلبي بمقدار ${nf.format(Math.round(-net))} ريال على مجمل الربح: الشركة لا تمرّر تغير التكلفة إلى أسعار البيع، وهذا يضغط الهامش.`)}
  if(!out.length)out.push("أدخل أصنافًا مشتركة بين الفترتين لحساب أثر الأسعار.");
  out.push("الأثر محسوب على الأصناف والمواد المشتركة بين الفترتين فقط، والباقي يظهر ضمن أثر الكميات والعوامل الأخرى.");
  return out;
}
