    roa:L(NI,ANN,TA),roe:L(NI,ANN,EQ),cogsRatio:L(CG,R),opexRatio:L(OX,R),finCostRatio:L(["تكاليف التمويل","interest"],R),
    expenseGrowth:L(["إجمالي المصروفات","totalExp"],P("إجمالي المصروفات","totalExp")),revenueGrowth:L(R,P("الإيرادات","revenue")),
    grossProfitGrowth:L(GP,P("مجمل الربح","gp")),netProfitGrowth:L(NI,P("صافي الربح","ni")),
    currentRatio:L(CA,CL),quickRatio:L(CA,["المخزون","inventory"],CL),cashRatio:L(["النقد وما في حكمه","cash"],CL),workingCapital:L(CA,CL),
    debtToEquity:L(["قروض قصيرة الأجل","shortDebt"],["قروض طويلة الأجل","longDebt"],EQ),debtRatio:L(TL,TA),
