    capitalAdequacy:L(EQ,TA),accLosses:L(["الأرباح المبقاة (الخسائر بالسالب)","retained"],["رأس المال المدفوع","capital"]),
    interestCoverage:L(EBIT,["تكاليف التمويل","interest"]),netDebtEbitda:L(["القروض","debt"],["النقد","cash"],EB,ANN),
    assetTurnover:L(R,ANN,TA),inventoryTurnover:L(CG,ANN,["مخزون الإنتاج (دون قطع الغيار)","prodInv"],["(−) المواد الخام والمساعدة","rmInv"],["المخزون المستخدم في المعادلة","fgInv"]),
    dso:L(["الذمم المدينة التجارية","tradeRec"],R,DAYS),dio:L(["مخزون الإنتاج (دون قطع الغيار)","prodInv"],["(−) المواد الخام والمساعدة","rmInv"],["المخزون المستخدم في المعادلة","fgInv"],CG,DAYS),dpo:L(["الذمم الدائنة التجارية","tradePay"],CG,DAYS),
    ccc:L(["فترة التحصيل",c=>c.revenue>0?c.tradeRec/c.revenue*c.days:null,"d"],["فترة بقاء المخزون",c=>c.cogs>0?c.prodInv/c.cogs*c.days:null,"d"],["فترة السداد",c=>c.cogs>0?c.tradePay/c.cogs*c.days:null,"d"]),
    sparesRatio:L(SP,["إجمالي المخزون قبل المخصص","grossInv"]),sparesDeadPct:L(["البطيئة","sparesSlow"],["الراكدة","sparesDead"],SP),
    sparesCover:L(SP,["المنصرف للصيانة في الفترة","sparesIssued"],["المنصرف الشهري المكافئ",c=>c.sparesIssued*c.ann/12]),
    sparesWorkCover:L(SP,["الراكدة","sparesDead"],["المنصرف الشهري المكافئ",c=>c.sparesIssued*c.ann/12]),
