    icNonTradeToEquity:L(["مدينة بالإنابة للشقيقة","icRN"],EQ),icNetToAssets:L(["مدينة تجارية","icRT"],["مدينة بالإنابة","icRN"],["دائنة تجارية","icPT"],["دائنة بالإنابة","icPN"],TA),
    icNonTradeChange:L(["مدينة بالإنابة للشقيقة","icRN"],P("مدينة بالإنابة للشقيقة","icRN")),
