async function tbMovers(p,cp){
  const pick=q=>q&&!q._virt&&q.month?reportsOf(q.company).find(r=>r.kind==="tb"&&r.year===q.year&&r.month===q.month&&r.months===1):null;
  const agg=async rep=>{if(!rep)return null;const R=await loadReport(rep._id);const L=R&&tbLines(R);if(!L)return null;const o={};
    L.forEach(l=>{if(!/^[4-7]/.test(l.ac))return;const v=l.ac[0]==="4"?(l.mc-l.md):(l.md-l.mc);const x=o[l.ac]=o[l.ac]||{ac:l.ac,nm:l.nm,v:0,cc:{}};x.v+=v;x.cc[l.cc||l.sec||""]=(x.cc[l.cc||l.sec||""]||0)+v});return o};
  const A=await agg(pick(p));if(!A)return "";const B=await agg(pick(cp));
  const rows=Object.values(A).map(x=>({...x,pv:B&&B[x.ac]?B[x.ac].v:0}));if(B)Object.values(B).forEach(y=>{if(!A[y.ac])rows.push({...y,pv:y.v,v:0,cc:{}})});
  const top=rows.map(x=>({...x,d:x.v-x.pv})).sort((a,b)=>Math.abs(B?b.d:b.v)-Math.abs(B?a.d:a.v)).slice(0,30);
  const F=v=>Math.round(v).toLocaleString("en-US");
  return `\nحركة حسابات قائمة الدخل من ميزان المراجعة (${B?`الأكبر تغيرًا بين ${plabel(p)} و${plabel(cp)}`:`الأكبر قيمة في ${plabel(p)}`}؛ الإيرادات موجبة والمصروفات موجبة):\n`+top.map(x=>`- ${x.ac} ${x.nm}: ${F(x.v)}${B?` | السابق ${F(x.pv)} | التغير ${x.d>=0?"+":""}${F(x.d)}`:""}${Object.keys(x.cc).length>1?` | حسب المركز: ${Object.entries(x.cc).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,3).map(([k,v])=>`${k} ${F(v)}`).join("، ")}`:""}`).join("\n");
}
