  const fillVoices=()=>{voices=((synth&&synth.getVoices())||[]).filter(v=>/^ar/i.test(v.lang)).sort((a,b)=>rankVoice(b)-rankVoice(a));
    $("#cVoice").innerHTML=voices.length?voices.map((v,i)=>`<option value="${i}" ${prefs.voice===v.name?"selected":""}>${esc(v.name)}${rankVoice(v)>=100?" ★":""}</option>`).join(""):`<option>لا يوجد صوت عربي</option>`;
    if(voices.length&&!voices.some(v=>v.name===prefs.voice))$("#cVoice").value="0"};
