function ipObj(id){const [y,m]=id.split("-");return {year:+y,month:m==="A"?0:+m}}
function openIssuesOf(cids){return Object.entries(D.issues).map(([id,i])=>({...i,_id:id})).filter(i=>cids.includes(i.company)&&i.status!=="closed")}
