const WF_ACT={save:"حفظ مبدئي",submit:"حفظ نهائي وإرسال لرئيس الحسابات",chiefApprove:"اعتماد رئيس الحسابات وإرسال للمدير المالي",cfoApprove:"اعتماد المدير المالي وإرسال للمدير التنفيذي للشركة",ccoApprove:"اعتماد نهائي تام من المدير التنفيذي للشركة",returnCfo:"إعادة للمدير المالي",return:"إعادة للمحاسب",returnChief:"إعادة لرئيس الحسابات",reopen:"إعادة فتح من مدير النظام",ask:"طلب توضيح",reply:"رد على طلب توضيح",comment:"تعليق",autoChief:"اعتماد آلي (رئيس الحسابات)",autoCfo:"اعتماد آلي (المدير المالي)"};
function lastRet(wf){const l=(wf.log||[]).slice(-1)[0];return l&&(l.action==="returnChief"||l.action==="returnCfo")?l:null}
function wfOf(p){return p.wf||{status:"draft",log:[],clar:[]}}
function myWfRoles(){const m=myMember();const r=new Set();if(isAdmin())r.add("admin");if(m)Object.entries(ROLE_POS).forEach(([k,v])=>{if(v.includes(m.position))r.add(k)});return r}
function authorOf(p){const wf=wfOf(p);if(wf.author)return wf.author;
  if(p.noteBy){const hit=Object.entries(D.members).find(([id,m])=>m.name===p.noteBy&&ROLE_POS.acc.includes(m.position));if(hit)return {id:hit[0],name:hit[1].name}}return null}
function isAuthor(p){const a=authorOf(p);return !!(a&&CUR&&a.id===CUR)}
function canReadAnalysis(p){const s=wfOf(p).status,r=myWfRoles();if(r.has("admin")||MODE!=="db")return true;
  if(r.has("acc")){const a=authorOf(p);return !a||a.id===CUR}
  if(r.has("chief"))return s!=="draft";if(r.has("cfo"))return ["chiefApproved","cfoApproved","final"].includes(s);if(r.has("cco"))return s==="cfoApproved"||s==="final";
  return s==="final"}
function membersInRole(role,cid,p){if(role==="acc"&&p){const a=authorOf(p);if(a&&D.members[a.id])return [[a.id,D.members[a.id]]]}
  return Object.entries(D.members).filter(([id,m])=>!isSuspended(m)&&ROLE_POS[role].includes(m.position)&&(!(m.companies||[]).length||m.companies.includes(cid)))}
function wfLogAdd(wf,action,note,to){return {...wf,log:[...(wf.log||[]),{action,by:myName(),at:Date.now(),note:note||"",from:wf.status||"draft",to:to||wf.status||"draft"}]}}
function wfComment(wf,role,text,kind){return {...wf,comments:[...(wf.comments||[]),{id:uid("c"),role,by:myName(),at:Date.now(),text,kind:kind||"note",stage:wf.status}]}}
