/* ---- 24h auto-approval ---- */
const WF_TIMEOUT=24*3600e3;
function stageStart(wf){if(wf.stageAt)return wf.stageAt;const L=(wf.log||[]);const a=wf.status==="submitted"?["submit","returnChief"]:["chiefApprove","autoChief","returnCfo"];const l=L.filter(x=>a.includes(x.action)).pop();return l?l.at:Date.now()}
let autoBusy=false;
async function autoAdvanceAll(){
  if(autoBusy||MODE==="loading"||(MODE==="db"&&(!CUR||role()==="none")))return;autoBusy=true;
  try{for(const [id,per] of Object.entries(D.periods)){let wf=per.wf;if(!wf||!["submitted","chiefApproved"].includes(wf.status))continue;
    let changed=false,now=Date.now();
    while(wf&&["submitted","chiefApproved"].includes(wf.status)){const start=stageStart(wf),due=start+WF_TIMEOUT;if(now<due)break;
      const chief=wf.status==="submitted";
      wf={...wf,status:chief?"chiefApproved":"cfoApproved",stageAt:due,
        log:[...(wf.log||[]),{action:chief?"autoChief":"autoCfo",by:"اعتماد آلي (النظام)",at:due,from:wf.status,to:chief?"chiefApproved":"cfoApproved",note:chief?"تم الاعتماد آليًا لعدم اعتماد رئيس الحسابات خلال 24 ساعة، وأُحيل للمدير المالي":"تم الاعتماد آليًا لعدم اعتماد المدير المالي خلال 24 ساعة، وأُحيل للمدير التنفيذي للشركة"}]};changed=true}
    if(changed){const cur=D.periods[id];if(cur&&cur.wf&&cur.wf.status===per.wf.status&&stageStart(cur.wf)===stageStart(per.wf))await put("periods",id,{...cur,wf})}}
  }finally{autoBusy=false}
}
function fmtLeft(ms){if(ms<0)ms=0;const s=Math.floor(ms/1000),h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(x).padStart(2,"0")}`}
setInterval(()=>{let expired=false;document.querySelectorAll("[data-deadline]").forEach(el=>{const left=+el.dataset.deadline-Date.now();el.textContent=fmtLeft(left);const box=el.closest(".wf-timer");if(box)box.classList.toggle("urgent",left<3600e3);if(left<=0)expired=true});if(expired)autoAdvanceAll()},1000);
setInterval(autoAdvanceAll,30000);

function periodLocked(p){return !!(p&&p.wf&&p.wf.status&&p.wf.status!=="draft")}
function lockMsg(p){return `البيانات المالية لـ ${plabel(p)} مقفلة لأن التحليل ${WF_LABEL[p.wf.status]}. لا يمكن تعديلها إلا بإعادة التحليل للمحاسب.`}
