  const used=Array.from({length:w},(_,i)=>i).filter(i=>rows.some(r=>r[i]!==""&&r[i]!=null&&String(r[i]).trim()!==""));
  const NC=new Set(used.filter(i=>body.some(r=>isNumCell(r[i]))));const numCol=i=>NC.has(i);
