function salesNotes(PA,PB){
  const a=PA.data||{},b=PB.data||{};const MA=a.salesMeta,MB=b.salesMeta;if(!MB||!Array.isArray(b.sales))return [];const N=[];
  const F=v=>nf.format(Math.round(Math.abs(v)));const P=v=>`${Math.abs(v).toFixed(1)}%`;const la=plabel(PA),lb=plabel(PB);
  // GL reconciliation for B
  if(b.slGross!=null){const gl=(Number(b.slGross)||0)+(Number(b.slTrade)||0);const d=MB.gross-gl;const disc=Number(b.slDisc)||0;
    N.push({lvl:Math.abs(d)<Math.max(1000,gl*0.002)?"good":"warn",t:`إجمالي تقرير المبيعات ${lb} (${F(MB.gross)}) ${Math.abs(d)<1?"يطابق":`يختلف بـ ${F(d)} عن`} حسابي المبيعات 411101 + 411102 (${F(gl)}). الأسعار في التقرير إجمالية قبل خصم الكمية وخصم الموزعين والمردودات، وهذه بلغت ${F(disc)} (${P(gl?disc/gl*100:0)} من المبيعات)، فصافي المبيعات أقل من متوسطات الأسعار المعروضة بهذه النسبة تقريبًا.`})}
  {const L=b.sales.filter(x=>x.qty>0&&x.price>0);const byT={};L.forEach(x=>{(byT[x.type||"_"]=byT[x.type||"_"]||[]).push(x.price)});
    const med=arr=>{const z=[...arr].sort((p,q)=>p-q);return z[Math.floor(z.length/2)]};
    const odd=L.filter(x=>{const arr=byT[x.type||"_"];return arr.length>=3&&x.price<med(arr)*0.2});
    if(odd.length)N.push({lvl:"warn",t:`أسعار شاذة في ${lb} تحتاج مراجعة إدخال: ${odd.map(x=>`${x.item} (${x.terms==="del"?"واصل":"مطروح"}) ${x.price.toFixed(2)} للوحدة، كمية ${nf.format(x.qty)}`).join("؛ ")}. متوسط أصناف نوعها أعلى بكثير.`})}
  if(b._glNote)N.unshift({lvl:"info",t:b._glNote});
  if(!MA||!Array.isArray(a.sales)||PA._id===PB._id)return N;
  // totals & decomposition
  const SA=aggItems(a.sales,"sales"),SB=aggItems(b.sales,"sales");let pe=0,matched=0,newV=0,lostV=0;const eff=[];
  Object.values(SB).forEach(x=>{const y=SA[x.key];if(y&&y.price>0&&x.price>0){const e=(x.price-y.price)*x.qty;pe+=e;matched++;eff.push({x,y,e,ch:(x.price/y.price-1)*100})}else newV+=x.value});
  Object.values(SA).forEach(y=>{if(!SB[y.key])lostV+=y.value});
  const dV=MB.gross-MA.gross,dQ=MB.qty-MA.qty,uA=MA.qty?MA.gross/MA.qty:0,uB=MB.qty?MB.gross/MB.qty:0;
  N.push({lvl:dV>=0?"good":"bad",t:`إجمالي المبيعات ${dV>=0?"ارتفع":"انخفض"} من ${F(MA.gross)} في ${la} إلى ${F(MB.gross)} في ${lb} (${dV>=0?"+":"−"}${F(dV)}، ${P(MA.gross?dV/MA.gross*100:0)}). الكمية ${dQ>=0?"زادت":"نقصت"} ${P(MA.qty?dQ/MA.qty*100:0)}، ومتوسط سعر الوحدة لكل المبيعات ${uB>=uA?"ارتفع":"انخفض"} من ${uA.toFixed(2)} إلى ${uB.toFixed(2)}.`});
  const volMix=dV-pe;N.push({lvl:pe<0?"warn":"info",t:`تحليل التغير: أثر تغيّر الأسعار على الأصناف المشتركة (${matched} صنفًا بشرط تسليم) ${pe>=0?"+":"−"}${F(pe)}، والباقي ${volMix>=0?"+":"−"}${F(volMix)} أثر الكمية ومزيج الأصناف${newV||lostV?` (منه أصناف جديدة ${F(newV)} وأصناف توقف بيعها ${F(lostV)})`:""}.`});
  // biggest price drops / rises by effect
  const drops=eff.filter(x=>x.e<0&&x.ch>-70).sort((p,q)=>p.e-q.e).slice(0,3),rises=eff.filter(x=>x.e>0&&x.ch<200).sort((p,q)=>q.e-p.e).slice(0,2);
  const T=t=>t==="del"?"واصل":"مطروح";
  if(drops.length)N.push({lvl:"bad",t:`أكبر أثر لانخفاض الأسعار: ${drops.map(x=>`${x.x.item} (${T(x.x.terms)}) من ${x.y.price.toFixed(2)} إلى ${x.x.price.toFixed(2)}، أثره −${F(x.e)}`).join("؛ ")}.`});
  if(rises.length)N.push({lvl:"good",t:`أكبر أثر لارتفاع الأسعار: ${rises.map(x=>`${x.x.item} (${T(x.x.terms)}) من ${x.y.price.toFixed(2)} إلى ${x.x.price.toFixed(2)}، أثره +${F(x.e)}`).join("؛ ")}.`});
  // delivered premium vs freight
  const prem=M=>{const S=aggItems(M===MB?b.sales:a.sales,"sales");let w=0,q=0;Object.values(S).filter(x=>x.terms==="del").forEach(x=>{const e=S[`${x.item}|ex|${x.unit}`];if(e&&e.price>0){w+=(x.price-e.price)*x.qty;q+=x.qty}});return q?w/q:null};
  const pA=prem(MA),pB=prem(MB),fA=MA.delQty?MA.fare/MA.delQty:null,fB=MB.delQty?MB.fare/MB.delQty:null;
  if(pB!=null&&fB!=null)N.push({lvl:pB<fB?"bad":"good",t:`فرق سعر الواصل عن المطروح للأصناف نفسها ${pB.toFixed(2)} ريال للوحدة في ${lb}${pA!=null?` مقابل ${pA.toFixed(2)} في ${la}`:""}، بينما أجرة النقل ${fB.toFixed(2)} ريال للوحدة الواصلة${fA!=null?` (${fA.toFixed(2)} في ${la})`:""}. ${pB<fB?`الواصل يُباع بأقل من تكلفة نقله بنحو ${F((fB-pB)*MB.delQty)} ${PB._virt?"خلال الفترة":"في الشهر"}، فراجع تسعير التوصيل.`:"فرق الواصل يغطي أجرة النقل."}`});
  // anomalies
  const odd=eff.filter(x=>x.ch<=-70||x.ch>=200);if(odd.length)N.push({lvl:"warn",t:`أسعار شاذة تحتاج مراجعة إدخال: ${odd.map(x=>`${x.x.item} (${T(x.x.terms)}) ${x.x.price.toFixed(2)} مقابل ${x.y.price.toFixed(2)}`).join("؛ ")}.`});
  // customer mix
  const sh=(M,k)=>M.byClass&&M.byClass[k]&&M.gross?M.byClass[k].v/M.gross*100:0;
  const cls=[...new Set([...Object.keys(MA.byClass||{}),...Object.keys(MB.byClass||{})])].map(k=>({k,a:sh(MA,k),b:sh(MB,k)})).filter(x=>Math.abs(x.b-x.a)>=2).sort((p,q)=>Math.abs(q.b-q.a)-Math.abs(p.b-p.a));
  if(cls.length)N.push({lvl:"info",t:`تغيّر مزيج العملاء: ${cls.map(x=>`${x.k} ${x.a.toFixed(0)}% ← ${x.b.toFixed(0)}%`).join("، ")} من قيمة المبيعات.`});
  return N;
}
function salesNotesHtml(PA,PB){const N=salesNotes(PA,PB);if(!N.length)return "";const ic={bad:"🔴",warn:"🟠",good:"🟢",info:"🔵"};
  return `<div class="ana-review sp-notes"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap"><b>ملاحظات المحلل — المبيعات (${plabel(PA)} مقابل ${plabel(PB)})</b>${DOWN&&Array.isArray(PA.data?.sales)&&Array.isArray(PB.data?.sales)?`<button class="btn sm primary" id="prSlx">📊 ملف Excel لتحليل الأسعار</button>`:""}</div><ul>${N.map(n=>`<li><span aria-hidden="true">${ic[n.lvl]}</span> ${esc(n.t)}</li>`).join("")}</ul><small>تُكتب تلقائيًا من تقرير المبيعات بالصنف وحسابات المبيعات في الميزان. الأسعار إجمالية قبل الخصومات والضريبة.</small></div>`}

